    ("Peak traffic", "peak_rps", ("cost", "api", "infra", "resilience")),
    ("Allowed providers", "allowed_target_providers", ("routing", "infra", "eval")),
    ("Availability target", "availability_target", ("resilience", "infra", "observe")),
    ("Identity provider", "identity_provider", ("auth", "api")),
    ("Compliance", "compliance", ("security", "data", "observe")),
